import sys
import os
import json

def count_content(content):
    """
    Calculates (lines, words, chars) from the given string content.
    """
    chars = len(content)
    words = len(content.split())

    if chars == 0:
        lines = 0
    else:
        newline_count = content.count('\n')
        if content.endswith('\n'):
            lines = newline_count
        else:
            lines = newline_count + 1

    return (lines, words, chars)

def read_input(filepath):
    """
    Reads content from filepath or stdin.
    """
    if filepath == '-':
        # Read as UTF-8 bytes with no newline translation
        return sys.stdin.buffer.read().decode('utf-8')
    else:
        with open(filepath, 'r', encoding='utf-8', newline='') as f:
            return f.read()

def generate_table(results):
    """
    Takes a list of tuples (lines, words, chars, filepath) and prints the formatted table.
    """
    # Initialize max widths with header length
    w_lines = len("lines")
    w_words = len("words")
    w_chars = len("chars")

    # Calculate total if needed for width considerations
    total_lines = sum(r[0] for r in results)
    total_words = sum(r[1] for r in results)
    total_chars = sum(r[2] for r in results)

    # Update widths based on individual rows
    for r in results:
        w_lines = max(w_lines, len(str(r[0])))
        w_words = max(w_words, len(str(r[1])))
        w_chars = max(w_chars, len(str(r[2])))

    # Update widths based on total row if it exists (2+ files)
    if len(results) >= 2:
        w_lines = max(w_lines, len(str(total_lines)))
        w_words = max(w_words, len(str(total_words)))
        w_chars = max(w_chars, len(str(total_chars)))

    # Print Header
    # Format: right-aligned numbers, left-aligned "file", separated by 2 spaces
    print(f"{'lines':>{w_lines}}  {'words':>{w_words}}  {'chars':>{w_chars}}  file")

    # Print Rows
    for r in results:
        lines, words, chars, filepath = r
        print(f"{lines:>{w_lines}}  {words:>{w_words}}  {chars:>{w_chars}}  {filepath}")

    # Print Total Row
    if len(results) >= 2:
        print(f"{total_lines:>{w_lines}}  {total_words:>{w_words}}  {total_chars:>{w_chars}}  total")

def main():
    args = sys.argv[1:]

    # Separate --json flag from file arguments
    json_mode = False
    file_args = []
    for arg in args:
        if arg == '--json':
            json_mode = True
        else:
            file_args.append(arg)

    # Check for usage error
    if not file_args:
        sys.stderr.write("usage: python wordcount.py FILE [FILE ...]\n")
        sys.exit(2)

    results = []
    error_occurred = False

    for filepath in file_args:
        # Special case for stdin
        if filepath == '-':
            try:
                content = read_input(filepath)
                lines, words, chars = count_content(content)
                results.append((lines, words, chars, filepath))
            except Exception:
                sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
                error_occurred = True
            continue

        # Check if it exists and is a regular file
        if not os.path.isfile(filepath):
            sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
            error_occurred = True
            continue

        try:
            content = read_input(filepath)
            lines, words, chars = count_content(content)
            results.append((lines, words, chars, filepath))
        except Exception:
            # File exists as regular file but cannot be read (e.g. permission)
            sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
            error_occurred = True
            continue

    if json_mode:
        files_data = [
            {
                "file": filepath,
                "lines": lines,
                "words": words,
                "chars": chars
            }
            for lines, words, chars, filepath in results
        ]

        total_lines = sum(r[0] for r in results)
        total_words = sum(r[1] for r in results)
        total_chars = sum(r[2] for r in results)

        output = {
            "files": files_data,
            "total": {
                "lines": total_lines,
                "words": total_words,
                "chars": total_chars
            }
        }

        # Print JSON object
        print(json.dumps(output))
    else:
        if not results:
            # Nothing printed to stdout if no readable files
            pass
        else:
            generate_table(results)

    if error_occurred:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()

