```python
import sys
import os
import json

def count_content(content):
    """Calculates lines, words, and chars from a string."""
    chars = len(content)
    words = len(content.split())

    if not content:
        lines = 0
    else:
        lines = content.count('\n')
        if not content.endswith('\n'):
            lines += 1

    return (lines, words, chars)

def count_file(filepath):
    """Reads the file and returns (lines, words, chars)."""
    try:
        # Open with newline='' to preserve \r\n as two chars
        with open(filepath, 'r', encoding='utf-8', newline='') as f:
            content = f.read()
    except Exception:
        return None

    return count_content(content)

def main():
    args = sys.argv[1:]

    # Extract --json flag
    use_json = False
    file_args = []
    for arg in args:
        if arg == '--json':
            use_json = True
        else:
            file_args.append(arg)

    if not file_args:
        sys.stderr.write("usage: python wordcount.py [- --json] FILE [FILE ...]\n")
        sys.exit(2)

    has_error = False
    results = []

    for filepath in file_args:
        if filepath == '-':
            try:
                stdin_bytes = sys.stdin.buffer.read()
                content = stdin_bytes.decode('utf-8')
                res = count_content(content)
                results.append((filepath, res[0], res[1], res[2]))
            except Exception:
                sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
                has_error = True
                continue
        elif not os.path.isfile(filepath):
            sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
            has_error = True
            continue
        else:
            res = count_file(filepath)
            if res is None:
                sys.stderr.write(f"wordcount.py: cannot read {filepath}\n")
                has_error = True
                continue

            results.append((filepath, res[0], res[1], res[2]))

    if use_json:
        json_files = []
        total_l = 0
        total_w = 0
        total_c = 0

        for filepath, l, w, c in results:
            json_files.append({
                "file": filepath,
                "lines": l,
                "words": w,
                "chars": c
            })
            total_l += l
            total_w += w
            total_c += c

        output = {
            "files": json_files,
            "total": {
                "lines": total_l,
                "words": total_w,
                "chars": total_c
            }
        }
        print(json.dumps(output))
    else:
        if not results:
            if has_error:
                sys.exit(1)
            sys.exit(0)

        # Determine column widths
        header = ["lines", "words", "chars", "file"]
        w_lines = len(header[0])
        w_words = len(header[1])
        w_chars = len(header[2])

        for _, l, w, c in results:
            w_lines = max(w_lines, len(str(l)))
            w_words = max(w_words, len(str(w)))
            w_chars = max(w_chars, len(str(c)))

        # Print header
        fmt_header = f"{'lines'.rjust(w_lines)}  {'words'.rjust(w_words)}  {'chars'.rjust(w_chars)}  {header[3]}"
        print(fmt_header)

        total_lines = 0
        total_words = 0
        total_chars = 0

        for filepath, l, w, c in results:
            print(f"{l:>{w_lines}}  {w:>{w_words}}  {c:>{w_chars}}  {filepath}")
            total_lines += l
            total_words += w
            total_chars += c

        if len(results) >= 2:
            print(f"{total_lines:>{w_lines}}  {total_words:>{w_words}}  {total_chars:>{w_chars}}  total")

    if has_error:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()
