import sys
import os
import argparse

LEVELS = {
    "INFO": 0,
    "WARN": 1,
    "ERROR": 2
}

def nonneg_int(x):
    try:
        val = int(x)
        if val < 0:
            raise ValueError
        return val
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid nonnegative integer value: '{x}'")

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("PATH")
    parser.add_argument("LEVEL")
    parser.add_argument("--at-least", action="store_true")
    parser.add_argument("--limit", type=nonneg_int)

    args = parser.parse_args()

    # Validate LEVEL: must be one of INFO, WARN, ERROR (case-insensitive)
    if args.LEVEL.upper() not in LEVELS:
        parser.error(f"invalid level: '{args.LEVEL}' (usage: logscan.py PATH LEVEL [--at-least] [--limit N])")

    return args

def main():
    args = parse_args()

    path = args.PATH
    target_level = args.LEVEL
    at_least = args.at_least
    limit = args.limit

    # Check if file exists and is a regular file
    if not os.path.exists(path) or not os.path.isfile(path):
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    try:
        with open(path, 'r', encoding='utf-8') as f:
            target_val = LEVELS[target_level.upper()]
            count = 0
            printed = 0

            for line in f:
                parts = line.split()
                if len(parts) < 3:
                    continue

                line_level = parts[2]
                # The spec states the level field must be exactly one of the 
                # uppercase words (INFO, WARN, ERROR).
                if line_level not in LEVELS:
                    continue

                line_val = LEVELS[line_level]

                matches = False
                if at_least:
                    if line_val >= target_val:
                        matches = True
                else:
                    if line_val == target_val:
                        matches = True

                if matches:
                    count += 1
                    if limit is None or printed < limit:
                        # Output the line exactly as it appears, followed by a newline.
                        if not line.endswith('\n'):
                            sys.stdout.write(line + '\n')
                        else:
                            sys.stdout.write(line)
                        printed += 1

            sys.stderr.write(f"count={count}\n")
            sys.exit(0)

    except (IOError, OSError):
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

if __name__ == '__main__':
    main()
