from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self._capacity = capacity
        self._cache = OrderedDict()

    def get(self, key, default=None):
        if key in self._cache:
            # Move accessed key to end to mark it as most recently used
            self._cache.move_to_end(key)
            return self._cache[key]
        return default

    def put(self, key, value):
        if key in self._cache:
            # Update existing key and move to end (MRU)
            self._cache[key] = value
            self._cache.move_to_end(key)
            return None

        # New key
        if len(self._cache) >= self._capacity:
            # Evict least recently used (first item in OrderedDict)
            lru_key, _ = self._cache.popitem(last=False)
            # Add new key as MRU
            self._cache[key] = value
            return lru_key
        else:
            # Add new key as MRU
            self._cache[key] = value
            return None

    def __len__(self):
        return len(self._cache)

    def __contains__(self, key):
        return key in self._cache

    def keys(self):
        return list(self._cache.keys())

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        self._capacity = capacity
        evicted = []

        # Evict LRU items until size fits new capacity
        while len(self._cache) > self._capacity:
            lru_key, _ = self._cache.popitem(last=False)
            evicted.append(lru_key)

        return evicted
