import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl is not None:
            if ttl <= 0:
                raise ValueError("TTL must be greater than 0")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock

        # Store key -> (value, timestamp)
        self._cache = OrderedDict()

        # Statistics
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _is_expired(self, key) -> bool:
        """Check if a key exists and is expired. If so, remove it and count expiration."""
        if key not in self._cache:
            return False

        if self.ttl is None:
            return False

        value, timestamp = self._cache[key]
        if self.clock() - timestamp >= self.ttl:
            del self._cache[key]
            self._expirations += 1
            return True

        return False

    def _purge_expired(self):
        """Remove all expired entries from the cache."""
        if self.ttl is None:
            return

        keys_to_check = list(self._cache.keys())
        for key in keys_to_check:
            self._is_expired(key)

    def get(self, key, default=None):
        if key in self._cache:
            if self._is_expired(key):
                self._misses += 1
                return default

            # It is valid
            self._hits += 1
            # Move to end to mark as recently used
            self._cache.move_to_end(key)
            return self._cache[key][0]

        self._misses += 1
        return default

    def put(self, key, value):
        # Check if key exists and if it's expired
        if key in self._cache:
            if self._is_expired(key):
                # It was removed by _is_expired. Now treat as new insertion.
                pass
            else:
                # Valid existing entry, update it
                self._cache[key] = (value, self.clock())
                self._cache.move_to_end(key)
                return None

        # Key is effectively new (never existed, or just expired and removed)
        # Clean up expired entries to ensure accurate capacity count
        self._purge_expired()

        evicted_key = None
        # If cache is full of unexpired entries, evict LRU
        if len(self._cache) >= self.capacity:
            # Pop the first item (least recently used unexpired)
            evicted_key, _ = self._cache.popitem(last=False)
            self._evictions += 1

        # Insert new entry
        self._cache[key] = (value, self.clock())

        return evicted_key

    def __contains__(self, key):
        if key not in self._cache:
            return False
        return not self._is_expired(key)

    def __len__(self):
        self._purge_expired()
        return len(self._cache)

    def keys(self):
        self._purge_expired()
        return list(self._cache.keys())

    def resize(self, new_capacity: int):
        if new_capacity < 1:
            raise ValueError("Capacity must be at least 1")

        self.capacity = new_capacity

        # Purge expired to get accurate unexpired count
        self._purge_expired()

        # Evict LRU unexpired entries if over new capacity
        while len(self._cache) > self.capacity:
            evicted_key, _ = self._cache.popitem(last=False)
            self._evictions += 1

    def stats(self) -> dict:
        # Purge to ensure any expired entries are counted before reporting stats
        self._purge_expired()
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
