    config = Config()
    lines = text.splitlines()

    current_section: str | None = None
    last_key: str | None = None
    # last_type can be 'key', 'continuation', or None (meaning no active multi-line value)
    last_type: str | None = None 

    for lineno, line in enumerate(lines, start=1):
        # Check for blank line
        if not line.strip():
            last_type = None
            continue

        # Check for comment
        stripped = line.strip()
        if stripped.startswith((';', '#')):
            last_type = None
            continue

        # Check for indented line (continuation or error)
        if line[0].isspace():
            # Must be a continuation line
            if last_key is None or last_type not in ('key', 'continuation'):
                raise ParseError(lineno, "Indented line without preceding key or continuation")

            # Append to current value
            content = stripped
            config._data[current_section][last_key] += '\n' + content
            last_type = 'continuation'
            continue

        # If we reach here, it's an unindented line, so any pending continuation ends
        last_key = None
        last_type = None

        # Check for section header
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            if not name:
                raise ParseError(lineno, "Empty section name")

            if name in config._data:
                raise ParseError(lineno, f"Duplicate section: {name}")

            current_section = name
            config._data[current_section] = {}
            continue

        # Check for key = value
        if '=' in line:
            if current_section is None:
                raise ParseError(lineno, "Key line before any section header")

            key_part, value_part = line.split('=', 1)
            key = key_part.strip()
            value = value_part.strip()

            if not key:
                raise ParseError(lineno, "Empty key")

            if key in config._data[current_section]:
                raise ParseError(lineno, f"Duplicate key: {key}")

            config._data[current_section][key] = value
            last_key = key
            last_type = 'key'
            continue

        # If none of the above matched, it's an invalid line
        raise ParseError(lineno, f"Invalid line: {line}")

    return config
