def satisfies(version, spec: str) -> bool:
    """
    Check if a version satisfies a range specification.

    Args:
        version: A Version object or a string representing a semantic version.
        spec: A string containing version range comparators separated by whitespace.

    Returns:
        True if the version satisfies all comparators in the spec, False otherwise.

    Raises:
        ValueError: If the spec is malformed or the version string is invalid.
    """
    # Convert version string to Version object
    if isinstance(version, str):
        try:
            version = Version.parse(version)
        except ValueError as e:
            raise ValueError(f"Invalid version: {version}") from e
    elif not isinstance(version, Version):
        raise TypeError(f"Expected Version or str, got {type(version)}")

    # Parse the specification into a list of (operator, bound) tuples
    try:
        comparators = _parse_spec(spec)
    except ValueError as e:
        # Re-raise with clear context if needed, or let it bubble up
        raise ValueError(f"Invalid spec '{spec}': {e}") from e

    # Check each comparator
    for op, bound in comparators:
        if op == '=':
            if version != bound:
                return False
        elif op == '>=':
            if version < bound:
                return False
        elif op == '<=':
            if version > bound:
                return False
        elif op == '>':
            if version <= bound:
                return False
        elif op == '<':
            if version >= bound:
                return False
        else:
            # Should not happen if _parse_comparator is correct
            raise ValueError(f"Unknown operator: {op}")

    return True
