def satisfies(version, spec: str) -> bool:
    """Check if a version satisfies a range spec.

    Args:
        version: A Version instance or a version string.
        spec: A range specification string (e.g., '^1.2.3', '>=1.0.0 <2.0.0').

    Returns:
        True if the version satisfies the spec, False otherwise.

    Raises:
        ValueError: If the version string or spec is invalid.
        TypeError: If version is not a Version or string.
    """
    if isinstance(version, str):
        try:
            v = Version.parse(version)
        except ValueError:
            raise ValueError(f"Invalid version string: {version}")
    elif isinstance(version, Version):
        v = version
    else:
        raise TypeError(f"version must be Version or str, got {type(version)}")

    if not spec or not spec.strip():
        raise ValueError("Empty spec")

    parts = spec.split()
    if not parts:
        raise ValueError("Empty spec")

    for part in parts:
        # Parse operator
        op = ''
        ver_str = part
        if len(part) > 1:
            if part.startswith('>='):
                op = '>='
                ver_str = part[2:]
            elif part.startswith('<='):
                op = '<='
                ver_str = part[2:]
            elif part.startswith('>'):
                op = '>'
                ver_str = part[1:]
            elif part.startswith('<'):
                op = '<'
                ver_str = part[1:]
            elif part.startswith('='):
                op = '='
                ver_str = part[1:]
            elif part.startswith('^'):
                op = '^'
                ver_str = part[1:]
            elif part.startswith('~'):
                op = '~'
