"""Semantic Versioning 2.0.0 parser and utilities."""

import re
import functools

# Regex for valid pre-release/build identifier
_IDENT_RE = re.compile(r'^[0-9A-Za-z-]+$')
# Regex for a numeric identifier (no leading zeros unless the value is "0")
_NUMERIC_NO_LEADING_ZEROS_RE = re.compile(r'^(0|[1-9][0-9]*)$')


def _validate_numeric_component(s: str) -> int:
    """Validate a numeric component (major/minor/patch): non-negative int, no leading zeros."""
    if not _NUMERIC_NO_LEADING_ZEROS_RE.match(s):
        raise ValueError(f"Invalid numeric component: {s!r}")
    return int(s)


def _parse_prerelease_or_build(text: str, *, allow_leading_zeros: bool) -> tuple:
    """Parse a prerelease or build string into a tuple of identifier strings.

    Args:
        text: The raw prerelease or build string (without leading - or +).
        allow_leading_zeros: If True, numeric identifiers may have leading zeros
                             (for build metadata). If False, they must not
                             (for prerelease).

    Returns:
        A tuple of identifier strings.

    Raises:
        ValueError: If any identifier is empty or contains invalid characters,
                    or if a prerelease numeric identifier has leading zeros.
    """
    if not text:
        raise ValueError("Prerelease/build string must not be empty")

    identifiers = text.split('.')
    if not identifiers or any(not id_ for id_ in identifiers):
        raise ValueError(f"Empty identifier in {text!r}")

    result = []
    for id_ in identifiers:
        if not _IDENT_RE.match(id_):
            raise ValueError(f"Invalid identifier: {id_!r}")
        # Check if it's a numeric identifier
        if id_.isdigit():
            if not allow_leading_zeros:
                # For prerelease, numeric identifiers must not have leading zeros
                if not _NUMERIC_NO_LEADING_ZEROS_RE.match(id_):
                    raise ValueError(
                        f"Numeric prerelease identifier {id_!r} has leading zeros"
                    )
        result.append(id_)

    return tuple(result)


class Version:
    """Represents a Semantic Version 2.0.0 version number."""

    __slots__ = ('major', 'minor', 'patch', 'prerelease', 'build', '_text')

    def __init__(self, major: int, minor: int, patch: int,
                 prerelease: tuple = (), build: tuple = (), _text: str = ''):
        object.__setattr__(self, 'major', major)
        object.__setattr__(self, 'minor', minor)
        object.__setattr__(self, 'patch', patch)
        object.__setattr__(self, 'prerelease', prerelease)
        object.__setattr__(self, 'build', build)
        object.__setattr__(self, '_text', _text)

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """Parse a SemVer 2.0.0 version string.

        Args:
            text: A version string in the form MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD].

        Returns:
            A Version instance.

        Raises:
            ValueError: If the string is not a valid SemVer 2.0.0 version.
        """
        # Disallow leading/trailing whitespace and 'v' prefix
        if text != text.strip():
            raise ValueError("Version string must not have surrounding whitespace")
        if text.startswith('v') or text.startswith('V'):
            raise ValueError("Version string must not start with 'v'")

        # Split off build metadata first
        if '+' in text:
            main_part, build_part = text.split('+', 1)
        else:
            main_part = text
            build_part = None

        # Split off prerelease
        if '-' in main_part:
            core_part, prerelease_part = main_part.split('-', 1)
        else:
            core_part = main_part
            prerelease_part = None

        # Validate core part
        core_parts = core_part.split('.')
        if len(core_parts) != 3:
            raise ValueError(
                f"Version must have exactly three core components (MAJOR.MINOR.PATCH), got {len(core_parts)}"
            )

        major_str, minor_str, patch_str = core_parts
        major = _validate_numeric_component(major_str)
        minor = _validate_numeric_component(minor_str)
        patch = _validate_numeric_component(patch_str)

        # Validate prerelease
        prerelease = ()
        if prerelease_part is not None:
            prerelease = _parse_prerelease_or_build(prerelease_part, allow_leading_zeros=False)

        # Validate build
        build = ()
        if build_part is not None:
            build = _parse_prerelease_or_build(build_part, allow_leading_zeros=True)

        return cls(major, minor, patch, prerelease, build, _text=text)

    def __str__(self) -> str:
        """Return the canonical text representation."""
        if self._text:
            return self._text
        parts = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            parts += '-' + '.'.join(self.prerelease)
        if self.build:
            parts += '+' + '.'.join(self.build)
        return parts

    def __repr__(self) -> str:
        return f"Version.parse('{self}')"

    def _compare_tuple(self, other_prerelease: tuple) -> int:
        """Compare prerelease tuples following SemVer precedence rules.

        Returns:
            -1 if self < other, 0 if equal, 1 if self > other.
        """
        self_pr = self.prerelease
        other_pr = other_prerelease

        # If both are empty, they are equal
        if not self_pr and not other_pr:
            return 0
        # If self has prerelease and other doesn't, self is lower
        if self_pr and not other_pr:
            return -1
        # If other has prerelease and self doesn't, self is higher
        if not self_pr and other_pr:
            return 1

        # Both have prerelease identifiers - compare left to right
        for s_id, o_id in zip(self_pr, other_pr):
            s_numeric = s_id.isdigit()
            o_numeric = o_id.isdigit()

            if s_numeric and o_numeric:
                # Both numeric: compare numerically
                s_val = int(s_id)
                o_val = int(o_id)
                if s_val < o_val:
                    return -1
                if s_val > o_val:
                    return 1
            elif s_numeric and not o_numeric:
                # Numeric < alphanumeric
                return -1
            elif not s_numeric and o_numeric:
                # Alphanumeric > numeric
                return 1
            else:
                # Both alphanumeric: compare in ASCII order
                if s_id < o_id:
                    return -1
                if s_id > o_id:
                    return 1
            # If equal, continue to next identifier

        # All compared identifiers were equal; shorter list is lower
        if len(self_pr) < len(other_pr):
            return -1
        if len(self_pr) > len(other_pr):
            return 1
        return 0

    def _compare_to(self, other: 'Version') -> int:
        """Compare self to other following SemVer precedence.

        Build metadata is ignored.

        Returns:
            -1, 0, or 1.
        """
        # Compare major, minor, patch
        if self.major < other.major:
            return -1
        if self.major > other.major:
            return 1
        if self.minor < other.minor:
            return -1
        if self.minor > other.minor:
            return 1
        if self.patch < other.patch:
            return -1
        if self.patch > other.patch:
            return 1

        # Same major.minor.patch, compare prerelease
        return self._compare_tuple(other.prerelease)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) < 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) <= 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) > 0

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) >= 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) == 0

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_to(other) != 0

    def __hash__(self):
        # Build metadata is ignored for equality, so it must not affect hash.
        # Prerelease is a tuple of strings that determines ordering among prereleases.
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def bump(self, kind: str) -> 'Version':
        """Return a new Version with the specified component bumped.

        Args:
            kind: One of 'major', 'minor', 'patch'.

        Returns:
            A new Version with the bumped component and no prerelease or build.

        Raises:
            ValueError: If kind is not one of 'major', 'minor', 'patch'.
        """
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: {kind!r}. Must be 'major', 'minor', or 'patch'.")
