def first_index(a: list, x) -> int:
    """
    Returns the index of the first element equal to x in the sorted list a.
    Returns -1 if x is not found.
    """
    left, right = 0, len(a)
    result = -1
    while left < right:
        mid = (left + right) // 2
        if a[mid] < x:
            left = mid + 1
        else:
            if a[mid] == x:
                result = mid
            right = mid
    return result


def last_index(a: list, x) -> int:
    """
    Returns the index of the last element equal to x in the sorted list a.
    Returns -1 if x is not found.
    """
    left, right = 0, len(a)
    result = -1
    while left < right:
        mid = (left + right) // 2
        if a[mid] > x:
            right = mid
        else:
            if a[mid] == x:
                result = mid
            left = mid + 1
    return result


def insertion_point(a: list, x) -> int:
    """
    Returns the smallest index i such that inserting x before a[i] keeps a sorted.
    This is equivalent to the lower bound of x.
    """
    left, right = 0, len(a)
    while left < right:
        mid = (left + right) // 2
        if a[mid] < x:
            left = mid + 1
        else:
            right = mid
    return left


def count(a: list, x) -> int:
    """
    Returns the number of occurrences of x in the sorted list a.
    """
    first = first_index(a, x)
    if first == -1:
        return 0
    last = last_index(a, x)
    return last - first + 1


def rotation_offset(a: list) -> int:
    """
    For a rotated sorted list of distinct values, returns the index of the smallest
    element (the pivot). Returns 0 if the list is not rotated.
    Raises ValueError if the list is empty.
    """
    if not a:
        raise ValueError("List must not be empty")

    left, right = 0, len(a) - 1
    while left < right:
        mid = (left + right) // 2
        if a[mid] > a[right]:
            # The minimum must be in the right half (after the pivot)
            left = mid + 1
        else:
            # The minimum is in the left half or is mid itself
            right = mid
    return left


def search_rotated(a: list, x) -> int:
    """
    Searches for x in a rotated sorted list of distinct values.
    Returns the index of x if found, otherwise -1.
    """
    if not a:
        return -1

    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            return mid

        # Determine which side is sorted
        if a[left] <= a[mid]:
            # Left side is sorted
            if a[left] <= x < a[mid]:
                # x is in the sorted left half
                right = mid - 1
            else:
                # x is in the right half
                left = mid + 1
        else:
            # Right side is sorted
            if a[mid] < x <= a[right]:
                # x is in the sorted right half
                left = mid + 1
            else:
                # x is in the left half
                right = mid - 1

    return -1

def isqrt(n: int) -> int:
    """
    Returns the largest integer r such that r * r <= n.
    Uses binary search for O(log n) iterations.
    Raises TypeError if n is not an int (bools are excluded).
    Raises ValueError if n is negative.
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be non-negative")

    if n == 0:
        return 0

    left, right = 1, n
    result = 0

    while left <= right:
        mid = (left + right) // 2
        # Calculate square. Python handles large integers natively, so no overflow risk.
        sq = mid * mid

        if sq == n:
            return mid
        elif sq < n:
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

