from collections import defaultdict
from typing import Any, Callable, Hashable, List, Tuple, Optional


class EmitError(Exception):
    """Exception raised when one or more listeners raise an exception during emission."""

    def __init__(self, errors: List[Tuple[Callable, Exception]], message: str = "One or more listeners raised an exception"):
        self.errors = errors
        super().__init__(message)


class Emitter:
    """A simple synchronous event emitter."""

    def __init__(self):
        # Dictionary mapping events to a list of listeners.
        # defaultdict handles access to unregistered events by automatically
        # creating an empty list for that key.
        # The list preserves registration order and allows duplicates.
        self._events: dict[Hashable, List[Callable]] = defaultdict(list)

    def on(self, event: Hashable, listener: Callable) -> Callable:
        self._events[event].append(listener)
        return listener

    def once(self, event: Hashable, listener: Callable) -> Callable:
        def wrapper(*args, **kwargs):
            self.off(event, wrapper)
            return listener(*args, **kwargs)
        wrapper._original = listener
        self._events[event].append(wrapper)
        return listener

    def off(self, event: Hashable, listener: Optional[Callable] = None) -> int:
        if event not in self._events:
            return 0

        listeners = self._events[event]

        if listener is None:
            count = len(listeners)
            del self._events[event]
            return count

        for i, reg in enumerate(listeners):
            if reg is listener or getattr(reg, '_original', None) is listener:
                listeners.pop(i)
                if not listeners:
                    del self._events[event]
                return 1
        return 0

    def listeners(self, event: Hashable) -> List[Callable]:
        """Returns the registered listeners for the event in registration order."""
        return list(self._events.get(event, []))

    def emit(self, event: Hashable, *args: Any, **kwargs: Any) -> int:
        """Calls listeners for the event. Returns number of calls made."""
        listeners_list = self._events.get(event)
        if not listeners_list:
            return 0

        # Snapshot the list at the start of emit
        snapshot = list(listeners_list)

        errors = []
        calls_made = 0

        for listener in snapshot:
            # Check if the listener is still registered (has not been removed by a previous listener)
            if listener not in self._events.get(event, []):
                continue

            try:
                listener(*args, **kwargs)
                calls_made += 1
            except Exception as e:
                calls_made += 1
                errors.append((listener, e))

        if errors:
            raise EmitError(errors)

        return calls_made
