# fsm/machine.py

from dataclasses import dataclass
from typing import Any, Callable, Optional


class MachineError(Exception):
    """Base exception for the FSM library."""
    pass


class InvalidTransition(MachineError):
    """Raised when no transition exists for the event from the current state."""
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition for event '{event}' from state '{state}'")
        self.state = state
        self.event = event


class GuardRejected(MachineError):
    """Raised when all transitions for an event from the current state are rejected by guards."""
    def __init__(self, state: str, event: str):
        super().__init__(f"All transitions for event '{event}' from state '{state}' were rejected by guards")
        self.state = state
        self.event = event


@dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None


@dataclass
class Transition:
    event: str
    source: Any  # state name, list/tuple of names, or '*'
    target: Optional[str]  # state name or None for internal
    guard: Optional[Callable] = None
    action: Optional[Callable] = None


@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict


def _source_matches(source: Any, current: str) -> bool:
    """Return True if *source* matches the current state name."""
    if source == '*':
        return True
    if isinstance(source, (list, tuple)):
        return current in source
    return source == current


class Machine:
    def __init__(self, states, transitions, initial: str, context=None):
        if not states:
            raise ValueError("states must not be empty")

        # Normalize state items: plain strings become State objects with no hooks.
        normalized: list[State] = []
        names: set[str] = set()
        for s in states:
            if isinstance(s, State):
                st = s
            elif isinstance(s, str):
                st = State(name=s)
            else:
                raise ValueError(f"Invalid state entry: {s!r}")
            if st.name in names:
                raise ValueError(f"Duplicate state name: {st.name!r}")
            names.add(st.name)
            normalized.append(st)

        if initial not in names:
            raise ValueError(f"Initial state {initial!r} is not a known state")

        # Validate transitions reference known states.
        for t in transitions:
            if t.source != '*':
                sources = t.source if isinstance(t.source, (list, tuple)) else [t.source]
                for src in sources:
                    if src not in names:
                        raise ValueError(
                            f"Transition for event {t.event!r} names unknown source state {src!r}"
                        )
            if t.target is not None and t.target not in names:
                raise ValueError(
                    f"Transition for event {t.event!r} names unknown target state {t.target!r}"
                )

        self._states: dict[str, State] = {s.name: s for s in normalized}
        self._transitions: list[Transition] = list(transitions)
        self._initial: str = initial
        self.context = context
        self.state: str = initial
        self.history: list[tuple[str, str, str]] = []
        self._listeners: list[Callable] = []
        self._firing: bool = False

    def _candidates(self, event_name: str, current: str) -> list[Transition]:
        """Return transitions whose event matches and source matches *current*, in order."""
        return [
            t for t in self._transitions
            if t.event == event_name and _source_matches(t.source, current)
        ]

    def fire(self, event_name: str, **data) -> str:
        if self._firing:
            raise MachineError("fire() called re-entrantly from within a hook")

        candidates = self._candidates(event_name, self.state)
        if not candidates:
            raise InvalidTransition(self.state, event_name)

        # Build the shared data dict once per fire call.
        data_dict = data

        self._firing = True
        try:
            current = self.state

            # Evaluate guards in candidate order; pick first that passes.
            chosen: Optional[Transition] = None
            for t in candidates:
                if t.guard is not None:
                    ev = Event(name=event_name, source=current, target=current, data=data_dict)
                    if not t.guard(self, ev):
                        continue
                chosen = t
                break

            if chosen is None:
                raise GuardRejected(current, event_name)

            if chosen.target is None:
                # Internal transition: only action, history, listeners.
                ev = Event(name=event_name, source=current, target=current, data=data_dict)
                if chosen.action is not None:
                    chosen.action(self, ev)
                self.history.append((current, event_name, current))
                for listener in self._listeners:
                    listener(current, ev, current)
            else:
                target = chosen.target
                ev = Event(name=event_name, source=current, target=target, data=data_dict)

                # on_exit of current state
                cur_state = self._states[current]
                if cur_state.on_exit is not None:
                    cur_state.on_exit(self, ev)

                # action
                if chosen.action is not None:
                    chosen.action(self, ev)

                # state change + history
                self.state = target
                self.history.append((current, event_name, target))

                # on_enter of target state
                tgt_state = self._states[target]
                if tgt_state.on_enter is not None:
                    tgt_state.on_enter(self, ev)

                # listeners
                for listener in self._listeners:
                    listener(current, ev, target)

            return self.state
        finally:
            self._firing = False

    def can_fire(self, event_name: str, **data) -> bool:
        current = self.state
        candidates = self._candidates(event_name, current)
        if not candidates:
            return False
        data_dict = data
        for t in candidates:
            if t.guard is None:
                return True
            ev = Event(name=event_name, source=current, target=current, data=data_dict)
            if t.guard(self, ev):
                return True
        return False

    def available_events(self) -> list[str]:
        current = self.state
        names: set[str] = set()
        for t in self._transitions:
            if t.source == '*' or (isinstance(t.source, (list, tuple)) and current in t.source) \
                    or t.source == current:
                names.add(t.event)
        return sorted(names)

    def on_transition(self, listener: Callable) -> None:
        self._listeners.append(listener)

    def reset(self) -> None:
        self.state = self._initial
        self.history = []
