# library/loans.py

import datetime
from dataclasses import dataclass
from collections.abc import Callable
from typing import Optional

from library.catalog import Catalog
from library.fines import POLICY, HOLD_PICKUP_DAYS, due_date, fine_for


class LoanError(Exception):
    pass

class Blocked(LoanError):
    pass

class DuplicateLoan(LoanError):
    pass

class LimitReached(LoanError):
    pass

class NotAvailable(LoanError):
    pass

class RenewalRefused(LoanError):
    pass

@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: datetime.date
    due: datetime.date
    renewals: int = 0
    returned: Optional[datetime.date] = None
    fine: int = 0


class Library:
    def __init__(self, catalog: Catalog, clock: Callable[[], datetime.date]):
        self.catalog = catalog
        self.clock = clock
        self._loans: dict[int, Loan] = {}
        self._next_loan_id = 1
        self._balances: dict[str, int] = {}
        # Holds per ISBN: list of dicts {'member_id': str, 'status': 'waiting'|'ready', 'deadline': date|None}
        self._holds: dict[str, list[dict]] = {}

    def _today(self) -> datetime.date:
        return self.clock()

    def _process_expiries(self):
        """Process hold expiries based on current date."""
        today = self._today()

        for isbn, queue in self._holds.items():
            if not queue:
                continue

            # We need to process expiries iteratively because removing one might promote the next
            changed = True
            while changed:
                changed = False
                # Find the first ready hold
                for i, hold in enumerate(queue):
                    if hold['status'] == 'ready' and hold['deadline'] < today:
                        # Expire this hold
                        queue.pop(i)
                        changed = True

                        # Try to promote the next waiting hold
                        if queue and queue[0]['status'] == 'waiting':
                            next_hold = queue[0]
                            next_hold['status'] = 'ready'
                            next_hold['deadline'] = today + datetime.timedelta(days=HOLD_PICKUP_DAYS)
                        break # Restart loop to check the new state

    def _get_member(self, member_id: str):
        return self.catalog.member(member_id)

    def _get_book(self, isbn: str):
        return self.catalog.book(isbn)

    def _get_loan(self, loan_id: int) -> Loan:
        return self._loans[loan_id]

    def _active_loans(self) -> list[Loan]:
        return [l for l in self._loans.values() if l.returned is None]

    def _active_loans_for_member(self, member_id: str) -> list[Loan]:
        return [l for l in self._active_loans() if l.member_id == member_id]

    def _active_loans_count(self, member_id: str) -> int:
        return len(self._active_loans_for_member(member_id))

    def _ready_holds_count(self, isbn: str) -> int:
        self._process_expiries()
        return sum(1 for h in self._holds.get(isbn, []) if h['status'] == 'ready')

    def _is_overdue(self, loan: Loan) -> bool:
        return self._today() > loan.due

    def available(self, isbn: str) -> int:
        self._process_expiries()
        book = self._get_book(isbn)
        active_count = sum(1 for l in self._active_loans() if l.isbn == isbn)
        ready_holds = self._ready_holds_count(isbn)
        return book.copies - active_count - ready_holds

    def checkout(self, member_id: str, isbn: str) -> Loan:
        self._process_expiries()

        member = self._get_member(member_id)
        book = self._get_book(isbn)

        # 1. Blocked
        balance = self._balances.get(member_id, 0)
        if balance > 0:
            raise Blocked(f"Member {member_id} has unpaid fines")

        # 2. Duplicate Loan
        active = self._active_loans_for_member(member_id)
        if any(l.isbn == isbn for l in active):
            raise DuplicateLoan(f"Member {member_id} already has {isbn}")

        # 3. Limit Reached
        policy = POLICY[member.kind]
        if len(active) >= policy.max_loans:
            raise LimitReached(f"Member {member_id} has reached max loans ({policy.max_loans})")

        # 4. Availability / Holds
        hold_idx = -1
        queue = self._holds.get(isbn, [])
        for i, h in enumerate(queue):
            if h['member_id'] == member_id:
                hold_idx = i
                break

        used_set_aside_copy = False
        if hold_idx != -1:
            hold = queue[hold_idx]
            if hold['status'] == 'ready':
                # Use set aside copy
                used_set_aside_copy = True
                queue.pop(hold_idx)
            else:
                # Waiting hold. Remove it as we are checking out.
                queue.pop(hold_idx)
                # We are taking a copy, so we don't need the hold anymore.

        if not used_set_aside_copy:
            # Check general availability
            # Recalculate available since we might have just popped a hold
            # Note: available() calls _process_expiries and calculates. 
            # But we just modified the queue. 
            if self.available(isbn) <= 0:
                raise NotAvailable(f"No copies available for {isbn}")

        # Create Loan
        today = self._today()
        due = due_date(today, policy.loan_days)
        loan = Loan(
            loan_id=self._next_loan_id,
            member_id=member_id,
            isbn=isbn,
            start=today,
            due=due
        )
        self._next_loan_id += 1
        self._loans[loan.loan_id] = loan

        return loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        self._process_expiries()

        self._get_member(member_id)
        self._get_book(isbn)

        # Check duplicates
        active = self._active_loans_for_member(member_id)
        if any(l.isbn == isbn for l in active):
            raise DuplicateLoan(f"Member {member_id} already has {isbn}")

        if isbn in self._holds:
            if any(h['member_id'] == member_id for h in self._holds[isbn]):
                raise DuplicateLoan(f"Member {member_id} already has a hold on {isbn}")

        # Check availability
        if self.available(isbn) > 0:
            raise LoanError("Item is available, no need to hold")

        # Add to queue
        if isbn not in self._holds:
            self._holds[isbn] = []

        hold_entry = {
            'member_id': member_id,
            'status': 'waiting',
            'deadline': None
        }
        self._holds[isbn].append(hold_entry)

        # Check if we can immediately make it ready (shouldn't happen if available was 0, 
        # but if there were expired holds processed just now, maybe?)
        # Actually, place_hold is called when available is 0. 
        # But if there is a gap in the queue logic, maybe.
        # The prompt says: "adds a waiting hold at the end... returns position".
        # It doesn't say it becomes ready immediately.
        # "When a copy is checked in... set aside for the earliest waiting hold".
        # So new holds are always waiting unless a copy was just returned and not set aside? 
        # No, copy setting aside happens on checkin.
        # So just return position.

        return len(self._holds[isbn])

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        self._process_expiries()

        self._get_member(member_id)
        self._get_book(isbn)

        if isbn not in self._holds:
            raise KeyError("No hold found")

        queue = self._holds[isbn]
        idx = -1
        removed_status = None
        for i, h in enumerate(queue):
            if h['member_id'] == member_id:
                idx = i
                removed_status = h['status']
                break

        if idx == -1:
            raise KeyError("No hold found")

        queue.pop(idx)

        # If we removed a ready hold, we need to pass the copy to the next waiting hold
        if removed_status == 'ready' and queue:
            if queue[0]['status'] == 'waiting':
                today = self._today()
                queue[0]['status'] = 'ready'
                queue[0]['deadline'] = today + datetime.timedelta(days=HOLD_PICKUP_DAYS)

    def holds(self, isbn: str) -> list[str]:
        self._process_expiries()
        self._get_book(isbn) # Validate isbn
        if isbn not in self._holds:
            return []
        return [h['member_id'] for h in self._holds[isbn]]

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, object]:
        self._process_expiries()
        self._get_member(member_id)
        self._get_book(isbn)

        if isbn not in self._holds:
            raise KeyError("No hold found")

        queue = self._holds[isbn]
        for i, h in enumerate(queue):
            if h['member_id'] == member_id:
                if h['status'] == 'ready':
                    return ('ready', h['deadline'])
                else:
                    return ('waiting', i + 1)

        raise KeyError("No hold found")

    def renew(self, loan_id: int) -> datetime.date:
        self._process_expiries()

        loan = self._get_loan(loan_id)

        if loan.returned is not None:
            raise LoanError("Loan already returned")

        member = self._get_member(loan.member_id)
        policy = POLICY[member.kind]

        # Check Renewal Refused conditions

        # 1. Overdue
        if self._is_overdue(loan):
            raise RenewalRefused("Loan is overdue")

        # 2. Has any hold
        if self._holds.get(loan.isbn, []):
            # If there are holds, renewal is refused? 
            # "RenewalRefused... if the isbn has any hold, waiting or ready"
            raise RenewalRefused("Item has pending holds")

        # 3. Renewals used
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("No renewals left")

        # Calculate new due date
        new_due = due_date(loan.due, policy.loan_days)
        loan.due = new_due
        loan.renewals += 1

        return new_due

    def checkin(self, loan_id: int) -> int:
        self._process_expiries()

        loan = self._get_loan(loan_id)

        if loan.returned is not None:
            raise LoanError("Loan already returned")

        member = self._get_member(loan.member_id)
        today = self._today()

        # Calculate fine
        fine = fine_for(member.kind, loan.due, today)

        # Update loan
        loan.returned = today
        loan.fine = fine

        # Update member balance
        if fine > 0:
            self._balances[member.member_id] = self._balances.get(member.member_id, 0) + fine

        # Pass copy to next waiting hold
        if loan.isbn in self._holds:
            queue = self._holds[loan.isbn]
            # Find first waiting hold
            for h in queue:
                if h['status'] == 'waiting':
                    h['status'] = 'ready'
                    h['deadline'] = today + datetime.timedelta(days=HOLD_PICKUP_DAYS)
                    break

        return fine

    def accrued_fine(self, loan_id: int) -> int:
        self._process_expiries()

        loan = self._get_loan(loan_id)

        if loan.returned is not None:
            return loan.fine

        member = self._get_member(loan.member_id)
        today = self._today()
        return fine_for(member.kind, loan.due, today)

    def balance(self, member_id: str) -> int:
        # Just return the stored balance. 
        # Should we check for accrued fines from active loans? 
        # The prompt says: "pay reduces the balance". "Blocked if the member's fine balance is above 0".
        # Balance is the sum of fines paid/accrued that haven't been paid? 
        # "adds it to the member's balance" on checkin.
        # So balance is strictly the accumulated fine debt.
        return self._balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        self._get_member(member_id)

        if amount <= 0:
            raise ValueError("Amount must be positive")

        balance = self._balances.get(member_id, 0)

        if amount > balance:
            raise ValueError("Amount exceeds balance")

        self._balances[member_id] = balance - amount
        return self._balances[member_id]

    def loans(self, member_id: str) -> list[Loan]:
        self._process_expiries()
        self._get_member(member_id)

        active = self._active_loans_for_member(member_id)
        active.sort(key=lambda l: (l.due, l.loan_id))
        return active

    def overdue(self) -> list[Loan]:
        self._process_expiries()
        today = self._today()

        overdue_loans = []
        for loan in self._active_loans():
            if loan.due < today:
                overdue_loans.append(loan)

        overdue_loans.sort(key=lambda l: (l.due, l.loan_id))
        return overdue_loans
