import re
from typing import Union


class FormulaError(ValueError):
    pass


class ErrorValue(str):
    """An error value that is a subclass of str."""
    pass


ERROR = ErrorValue("#ERROR!")
CYCLE = ErrorValue("#CYCLE!")


# --- Syntax Tree Nodes ---

class Expr:
    """Base class for all expression nodes."""
    pass


class Number(Expr):
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self):
        return f"Number({self.value!r})"


class Ref(Expr):
    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return f"Ref({self.name!r})"


class Unary(Expr):
    def __init__(self, op: str, operand: Expr):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"Unary({self.op!r}, {self.operand!r})"


class Binary(Expr):
    def __init__(self, op: str, left: Expr, right: Expr):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"Binary({self.op!r}, {self.left!r}, {self.right!r})"


# --- Tokenizer ---

_TOKEN_RE = re.compile(r"""
    (?P<WS>\s+)|
    (?P<NUMBER>\d+(?:\.\d+)?)|
    (?P<REF>[A-Za-z]\d+)|
    (?P<OP>[+\-*/])|
    (?P<LPAREN>\()|
    (?P<RPAREN>\))
""", re.VERBOSE)


def _tokenize(source: str):
    tokens = []
    pos = 0
    n = len(source)
    while pos < n:
        m = _TOKEN_RE.match(source, pos)
        if not m:
            raise FormulaError(f"Invalid character at position {pos}: {source[pos]!r}")
        pos = m.end()
        kind = m.lastgroup
        text = m.group()
        if kind == "WS":
            continue
        tokens.append((kind, text))
    return tokens


# --- Parser ---

class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def consume(self, expected_kind=None):
        if self.pos >= len(self.tokens):
            raise FormulaError("Unexpected end of input")
        kind, text = self.tokens[self.pos]
        if expected_kind is not None and kind != expected_kind:
            raise FormulaError(f"Expected {expected_kind}, got {kind} ({text!r})")
        self.pos += 1
        return kind, text

    def parse(self) -> Expr:
        expr = self.parse_expr()
        if self.pos < len(self.tokens):
            raise FormulaError("Unexpected trailing tokens")
        return expr

    def parse_expr(self) -> Expr:
        left = self.parse_term()
        while True:
            kind, text = self.peek()
            if kind == "OP" and text in (+"", "-"):
                self.consume("OP")
                right = self.parse_term()
                left = Binary(text, left, right)
            else:
                break
        return left

    def parse_term(self) -> Expr:
        left = self.parse_unary()
        while True:
            kind, text = self.peek()
            if kind == "OP" and text in ("*", "/"):
                self.consume("OP")
                right = self.parse_unary()
                left = Binary(text, left, right)
            else:
                break
        return left

    def parse_unary(self) -> Expr:
        kind, text = self.peek()
        if kind == "OP" and text in ("+", "-"):
            self.consume("OP")
            operand = self.parse_unary()
            return Unary(text, operand)
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        kind, text = self.peek()
        if kind == "NUMBER":
            self.consume("NUMBER")
            if "." in text:
                return Number(float(text))
            else:
                return Number(int(text))
        elif kind == "REF":
            self.consume("REF")
            name = text.upper()
            # Validate reference: 1 letter, row 1-999, no leading zeros
            m = re.fullmatch(r"([A-Z])(\d+)", name)
            if not m:
                raise FormulaError(f"Invalid reference: {text!r}")
            col, row_str = m.groups()
            if len(col) != 1:
                raise FormulaError(f"Invalid reference: {text!r}")
            # Check for leading zeros in row
            if len(row_str) > 1 and row_str[0] == '0':
                raise FormulaError(f"Invalid reference: {text!r}")
            row = int(row_str)
            if row < 1 or row > 999:
                raise FormulaError(f"Invalid reference: {text!r}")
            return Ref(name)
        elif kind == "LPAREN":
            self.consume("LPAREN")
            expr = self.parse_expr()
            self.consume("RPAREN")
            return expr
        else:
            raise FormulaError(f"Unexpected token: {text!r}")


def parse_formula(source: str) -> Expr:
    """Parse formula text (after '=') into a syntax tree."""
    if source == "":
        raise FormulaError("Empty formula")
    tokens = _tokenize(source)
    parser = _Parser(tokens)
    tree = parser.parse()
    return tree


def references(tree: Expr) -> set[str]:
    """Extract upper-case cell references from the syntax tree."""
    refs = set()
    _collect_refs(tree, refs)
    return refs


def _collect_refs(node: Expr, refs: set):
    if isinstance(node, Ref):
        refs.add(node.name)
    elif isinstance(node, Unary):
        _collect_refs(node.operand, refs)
    elif isinstance(node, Binary):
        _collect_refs(node.left, refs)
        _collect_refs(node.right, refs)


def evaluate(tree: Expr, lookup):
    """Evaluate the formula tree.

    lookup(name) returns the current value of the named cell.
    Returns: int, float, str (text), None (shouldn't happen if handled), or ErrorValue.
    """
    return _eval_node(tree, lookup)


def _eval_node(node: Expr, lookup):
    if isinstance(node, Number):
        return node.value

    elif isinstance(node, Ref):
        val = lookup(node.name)
        if val is None:
            return 0
        return val

    elif isinstance(node, Unary):
        operand = _eval_node(node.operand, lookup)
        # Check for error
        if isinstance(operand, ErrorValue):
            return operand
        # Check for text
        if isinstance(operand, str) and not isinstance(operand, ErrorValue):
            return ERROR
        # Apply unary operator
        if node.op == "+":
            return operand
        elif node.op == "-":
            if isinstance(operand, int):
                return -operand
            elif isinstance(operand, float):
                return -operand
            else:
                return ERROR
        else:
            return ERROR

    elif isinstance(node, Binary):
        left = _eval_node(node.left, lookup)
        right = _eval_node(node.right, lookup)

        # Check for errors first
        left_is_error = isinstance(left, ErrorValue)
        right_is_error = isinstance(right, ErrorValue)

        if left_is_error and right_is_error:
            return left
        elif left_is_error:
            return left
        elif right_is_error:
            return right

        # Check for text (non-error strings)
        left_is_text = isinstance(left, str) and not isinstance(left, ErrorValue)
        right_is_text = isinstance(right, str) and not isinstance(right, ErrorValue)

        if left_is_text or right_is_text:
            return ERROR

        # Now both should be numeric (int or float)
        # Determine result type: float if either is float, else int
        is_float = isinstance(left, float) or isinstance(right, float)

        op = node.op
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        elif op == "*":
            result = left * right
        elif op == "/":
            if right == 0:
                return ERROR
            result = left / right
            return float(result)
        else:
            return ERROR

        if op == "/":
            return float(result)

        if is_float:
            return float(result)
        else:
            return int(result)

    return ERROR
