class DependencyGraph:
    """Tracks dependency relationships between cells."""

    def __init__(self):
        # Maps cell -> set of cells it depends on (precedents)
        self._precedents = {}
        # Maps cell -> set of cells that depend on it (dependents)
        self._dependents = {}

    def set_dependencies(self, cell: str, precedents):
        """Replace the precedents of `cell` with the given iterable."""
        # Remove old reverse links
        old_precedents = self._precedents.get(cell, set())
        for p in old_precedents:
            if cell in self._dependents.get(p, set()):
                self._dependents[p].discard(cell)
                # Optional cleanup if empty
                if not self._dependents[p]:
                    del self._dependents[p]

        new_precedents = set(precedents)
        # Add new forward links
        if new_precedents:
            self._precedents[cell] = new_precedents
        elif cell in self._precedents:
            del self._precedents[cell]

        # Add new reverse links
        for p in new_precedents:
            self._dependents.setdefault(p, set()).add(cell)

    def precedents(self, cell: str) -> set[str]:
        """Return the direct precedents of `cell`."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> set[str]:
        """Return the direct dependents of `cell`."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> set[str]:
        """Return all cells that depend on `cell`, directly or transitively."""
        visited = set()
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            # Get direct dependents of current
            for d in self._dependents.get(curr, set()):
                if d not in visited:
                    stack.append(d)

        # Remove the starting cell if it doesn't depend on itself directly 
        # or transitively (i.e. if it's not in a cycle involving itself)
        # The spec says: "It contains cell itself only when cell is on a cycle."
        # If cell is visited via a path from itself, it is in a cycle.
        # Since we start with cell in stack, it is always in visited.
        # We need to check if there is a path from cell back to cell.
        # Actually, simpler logic: If cell is in the set of nodes reached 
        # from a dependent of cell, then it's a cycle.

        # Let's refine: standard BFS/DFS from cell's dependents.
        # If we reach cell, then cell is on a cycle.

        # Reset logic to follow spec strictly.
        # all_dependents includes cells that refer to cell.
        # cell itself is included ONLY if cell is on a cycle.

        visited_excluding_self = set()
        stack = list(self._dependents.get(cell, set()))
        cycle_detected = False

        while stack:
            curr = stack.pop()
            if curr == cell:
                cycle_detected = True
                continue
            if curr in visited_excluding_self:
                continue
            visited_excluding_self.add(curr)
            for d in self._dependents.get(curr, set()):
                if d == cell:
                    cycle_detected = True
                elif d not in visited_excluding_self:
                    stack.append(d)

        if cycle_detected:
            visited_excluding_self.add(cell)

        return visited_excluding_self

    def cycle_cells(self) -> set[str]:
        """Return every cell that lies on a cycle."""
        # Find Strongly Connected Components (SCCs)
        # Using iterative Tarjan's or Kosaraju's

        # Kosaraju's algorithm iterative approach might be tricky to implement cleanly.
        # Let's use a simple DFS-based cycle detection or iterative Tarjan.

        # Simpler approach for finding all nodes in cycles:
        # A node is in a cycle if it is part of an SCC of size > 1 OR has a self-loop.

        # Let's find all SCCs using Kosaraju's

        # Step 1: Order by finish time
        visited = set()
        order = []

        # Iterative DFS for first pass
        # We need to handle all nodes that have precedents or dependents
        nodes = set(self._precedents.keys()) | set(self._dependents.keys())

        for start in nodes:
            if start in visited:
                continue
            stack = [(start, False)] # (node, processed_children)
            while stack:
                node, processed = stack.pop()
                if processed:
                    visited.add(node)
                    order.append(node)
                    continue
                if node in visited:
                    continue
                stack.append((node, True))
                # Push children (precedents) unvisited
                for p in self._precedents.get(node, set()):
                    if p not in visited:
                        stack.append((p, False))

        # Step 2: Reverse graph DFS in reverse finish order
        visited.clear()
        sccs = []
        current_scc = []

        # Reverse graph edges are dependents -> precedents? 
        # Original edge: cell depends on precedent. So edge cell -> precedent.
        # Reverse edge: precedent -> cell. Which is exactly self._dependents[p] contains cell.
        # So in reverse graph, outgoing edges from a node `u` are `self._dependents.get(u)`.

        for node in reversed(order):
            if node in visited:
                continue
            # Start new SCC
            stack = [node]
            scc = []
            while stack:
                curr = stack.pop()
                if curr in visited:
                    continue
                visited.add(curr)
                scc.append(curr)
                # In reverse graph, neighbors are dependents
                for d in self._dependents.get(curr, set()):
                    if d not in visited:
                        stack.append(d)
            sccs.append(scc)

        # Filter SCCs: size > 1 OR self-loop
        cycle_nodes = set()
        for scc in sccs:
            if len(scc) > 1:
                cycle_nodes.update(scc)
            elif len(scc) == 1:
                node = scc[0]
                # Check for self-loop
                if node in self._precedents.get(node, set()):
                    cycle_nodes.add(node)

        return cycle_nodes
