            stack = [node]
            scc = []
            while stack:
                curr = stack.pop()
                if curr in visited:
                    continue
                visited.add(curr)
                scc.append(curr)
                # In reverse graph, neighbors are dependents
                for d in self._dependents.get(curr, set()):
