                # In reverse graph, neighbors are dependents
                for d in self._dependents.get(curr, set()):
                    if d not in visited:
                        stack.append(d)
            sccs.append(scc)

        # Filter SCCs: size > 1 OR self-loop
        cycle_nodes = set()
        for scc in sccs:
            if len(scc) > 1:
                cycle_nodes.update(scc)
            elif len(scc) == 1:
                node = scc[0]
                # Check for self-loop
                if node in self._precedents.get(node, set()):
                    cycle_nodes.add(node)

        return cycle_nodes
