@total_ordering
class Version:
    """Represents a MAJOR.MINOR.PATCH version."""

    def __init__(self, text):
        if not isinstance(text, str):
            raise ValueError("Version must be a string")

        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: {text!r}")

        nums = []
        for p in parts:
            if not p.isdigit():
                raise ValueError(f"Invalid version component: {p!r}")
            if len(p) > 1 and p[0] == '0':
                raise ValueError(f"Invalid version component: {p!r}")
            nums.append(int(p))

        self.major, self.minor, self.patch = nums
        self._str = f"{self.major}.{self.minor}.{self.patch}"

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._as_tuple() == other._as_tuple()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._as_tuple() < other._as_tuple()

    def _as_tuple(self):
        return (self.major, self.minor, self.patch)

    def __hash__(self):
        return hash(self._as_tuple())

    def __str__(self):
        return self._str

    def __repr__(self):
        return f"Version('{str(self)}')"


class Range:
    """Represents a range of versions defined by constraints."""

    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError("Range spec must be a string")

        # Handle empty spec
        stripped_spec = spec.strip()
        if not stripped_spec:
             # An empty spec usually means "no constraint" but the prompt says:
             # "An empty spec ... raises ValueError"? 
             # Wait, prompt says: "An empty spec, an empty constraint (as in `>=1.0.0,`), ... raises ValueError"
             # However, '*' is often used for 'any'. If spec is "*", it's valid.
             # If spec is "", it raises ValueError.
             raise ValueError("Empty range spec")

        self._constraints = []
        self._spec = spec

        # Split by comma, handle whitespace around constraints
        raw_constraints = stripped_spec.split(',')

        # Validate empty constraints (e.g. "", "a,,b", "a, ")
        if not raw_constraints:
             raise ValueError("Empty range spec")

        for c in raw_constraints:
            c_stripped = c.strip()
            if not c_stripped:
                raise ValueError(f"Empty constraint in spec: {spec!r}")
            self._parse_constraint(c_stripped)

        # Canonical string representation (whitespace removed)
        self._canonical_str = ",".join(str(c) for c in self._constraints)

    def _parse_constraint(self, text):
        text = text.strip()
        if text == "*":
            self._constraints.append(_AnyConstraint())
            return

        # Check for operators: >=, <=, !=, >, <, ==, ^, ~
        # Order matters for matching prefix
        if text.startswith("=="):
            v_str = text[2:].strip()
            self._constraints.append(_ExactConstraint(Version(v_str)))
        elif text.startswith("!="):
            v_str = text[2:].strip()
            self._constraints.append(_NotEqualConstraint(Version(v_str)))
        elif text.startswith(">="):
            v_str = text[2:].strip()
            self._constraints.append(_GteConstraint(Version(v_str)))
        elif text.startswith("<="):
            v_str = text[2:].strip()
            self._constraints.append(_LteConstraint(Version(v_str)))
        elif text.startswith(">"):
            v_str = text[1:].strip()
            self._constraints.append(_GtConstraint(Version(v_str)))
        elif text.startswith("<"):
            v_str = text[1:].strip()
            self._constraints.append(_LtConstraint(Version(v_str)))
        elif text.startswith("^"):
            v_str = text[1:].strip()
            v = Version(v_str)
            self._constraints.append(_CaretConstraint(v))
        elif text.startswith("~"):
            v_str = text[1:].strip()
            v = Version(v_str)
            self._constraints.append(_TildeConstraint(v))
        else:
            # Implicitly "==" if it looks like a version
            if re.match(r"^\d+\.\d+\.\d+$", text):
                 self._constraints.append(_ExactConstraint(Version(text)))
            else:
                raise ValueError(f"Unknown operator or malformed constraint: {text!r}")

    def contains(self, v):
        if not isinstance(v, Version):
            raise ValueError("Must pass a Version object")
        return all(c.contains(v) for c in self._constraints)

    def __contains__(self, v):
        return self.contains(v)

    def __str__(self):
        return self._canonical_str

    def __repr__(self):
        return f"Range('{str(self)}')"


class _Constraint:
    def contains(self, v):
        raise NotImplementedError

    def __str__(self):
        return self._str


class _AnyConstraint(_Constraint):
    def __init__(self):
        self._str = "*"

    def contains(self, v):
        return True


class _ExactConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f"=={str(v)}"

    def contains(self, v):
        return v == self.v


class _NotEqualConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f"!={str(v)}"

    def contains(self, v):
        return v != self.v


class _GtConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f">{str(v)}"

    def contains(self, v):
        return v > self.v


class _GteConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f">={str(v)}"

    def contains(self, v):
        return v >= self.v


class _LtConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f"<{str(v)}"

    def contains(self, v):
        return v < self.v


class _LteConstraint(_Constraint):
    def __init__(self, v):
        self.v = v
        self._str = f"<={str(v)}"

    def contains(self, v):
        return v <= self.v


class _CaretConstraint(_Constraint):
    """^X.Y.Z behaves as >=X.Y.Z and < next version of leftmost non-zero part."""
    def __init__(self, v):
        self.v = v
        self._str = f"^{str(v)}"
        self.lower = v

        if self.v.major != 0:
            self.upper = Version(f"{self.v.major + 1}.0.0")
        elif self.v.minor != 0:
            self.upper = Version(f"0.{self.v.minor + 1}.0")
        elif self.v.patch != 0:
            # ^0.0.3 is >=0.0.3, <0.0.4
            # But prompt says ^0.0.0 is >=0.0.0, <0.0.1
            # And ^0.0.3 is >=0.0.3, <0.0.4? 
            # Let's re-read carefully:
            # ^1.2.3 -> >=1.2.3, <2.0.0
            # ^0.2.3 -> >=0.2.3, <0.3.0
            # ^0.0.3 -> >=0.0.3, <0.0.4
            # ^0.0.0 -> >=0.0.0, <0.0.1
            # This implies if major is 0, check minor. If minor is 0, check patch.
            # Upper bound is bump of leftmost non-zero.
            # If 0.0.3, leftmost non-zero is patch. Next is 0.0.4.
            self.upper = Version(f"0.0.{self.v.patch + 1}")
        else:
            # 0.0.0
            self.upper = Version("0.0.1")

    def contains(self, v):
        return self.lower <= v < self.upper


class _TildeConstraint(_Constraint):
    """~X.Y.Z behaves as >=X.Y.Z and <X.Y+1.0"""
    def __init__(self, v):
        self.v = v
        self._str = f"~{str(v)}"
        self.lower = v
        self.upper = Version(f"{self.v.major}.{self.v.minor + 1}.0")

    def contains(self, v):
        return self.lower <= v < self.upper
