from .versions import Version, Range


class PackageIndex:
    """A data store for available packages and their dependencies."""

    def __init__(self):
        # Maps package name to a dictionary: {Version: {dep_name: Range}}
        self._packages = {}

    def add(self, name, version, requires=None):
        """
        Add a release to the index.

        Args:
            name: Package name.
            version: Version string.
            requires: Optional dict mapping dependency names to range spec strings.

        Raises:
            ValueError: If version or spec is invalid, or if (name, version) already exists.
        """
        if requires is None:
            requires = {}

        # Validate and parse version
        try:
            v = Version(version)
        except ValueError:
            raise ValueError(f"Invalid version: {version}")

        # Validate and parse dependencies
        parsed_requires = {}
        for dep_name, spec in requires.items():
            try:
                r = Range(spec)
            except ValueError:
                raise ValueError(
                    f"Invalid range spec for dependency '{dep_name}': {spec}"
                )
            parsed_requires[dep_name] = r

        if name not in self._packages:
            self._packages[name] = {}

        if v in self._packages[name]:
            raise ValueError(
                f"Duplicate entry for {name} version {v}"
            )

        self._packages[name][v] = parsed_requires

    def versions(self, name):
        """
        Return a list of known Versions for a package, newest first.

        Args:
            name: Package name.

        Returns:
            List of Version objects, sorted descending. Empty list if unknown.
        """
        if name not in self._packages:
            return []

        vers = list(self._packages[name].keys())
        vers.sort(reverse=True)
        return vers

    def requirements(self, name, version):
        """
        Return the dependency requirements for a specific package release.

        Args:
            name: Package name.
            version: Version object (or string) for the release.

        Returns:
            Dict mapping dependency names to Range objects.

        Raises:
            KeyError: If the package/version combination is not found.
        """
        if name not in self._packages:
            raise KeyError(name)

        # Allow passing string or Version object
        if not isinstance(version, Version):
            try:
                v = Version(version)
            except ValueError:
                raise KeyError((name, version))
        else:
            v = version

        if v not in self._packages[name]:
            raise KeyError((name, v))

        return self._packages[name][v]

    @classmethod
    def from_dict(cls, data):
        """
        Build an index from a nested dictionary structure.

        Args:
            data: Dict mapping package names to {version: {dep: spec, ...}, ...}

        Returns:
            A populated PackageIndex.
        """
        index = cls()
        for name, releases in data.items():
            for version, requires in releases.items():
                index.add(name, version, requires)
        return index
