# resolve/versions.py
"""Version and Range types for package dependency resolution."""


def _parse_version_parts(text):
    """Parse a version string, returning (major, minor, patch) integers.

    Raises ValueError if the format is invalid.
    """
    parts = text.split('.')
    if len(parts) != 3:
        raise ValueError(f"Version must have exactly 3 parts: {text!r}")
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid version component: {part!r} in {text!r}")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zeros are not allowed: {text!r}")
    return int(parts[0]), int(parts[1]), int(parts[2])


class Version:
    """A parsed package version (MAJOR.MINOR.PATCH)."""

    __slots__ = ('_major', '_minor', '_patch')

    def __init__(self, text):
        self._major, self._minor, self._patch = _parse_version_parts(text)

    @property
    def major(self):
        return self._major

    @property
    def minor(self):
        return self._minor

    @property
    def patch(self):
        return self._patch

    def __str__(self):
        return f"{self._major}.{self._minor}.{self._patch}"

    def __repr__(self):
        return f"Version({str(self)!r})"

    def _key(self):
        return (self._major, self._minor, self._patch)

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._key() == other._key()
        return NotImplemented

    def __ne__(self, other):
        if isinstance(other, Version):
            return self._key() != other._key()
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._key() < other._key()
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, Version):
            return self._key() <= other._key()
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, Version):
            return self._key() > other._key()
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, Version):
            return self._key() >= other._key()
        return NotImplemented

    def __hash__(self):
        return hash(self._key())


# Operators matched in priority order (longest first to prevent mis-parsing)
_OPERATORS = ('>=', '<=', '!=', '==', '>', '<', '^', '~')


def _caret_upper_bound(ver):
    """Compute the exclusive upper bound for a caret (^) range."""
    if ver.major != 0:
        return Version(f"{ver.major + 1}.0.0")
    if ver.minor != 0:
        return Version(f"0.{ver.minor + 1}.0")
    if ver.patch != 0:
        return Version(f"0.0.{ver.patch + 1}")
    return Version("0.0.1")


def _tilde_upper_bound(ver):
    """Compute the exclusive upper bound for a tilde (~) range."""
    return Version(f"{ver.major}.{ver.minor + 1}.0")


def _parse_single_constraint(text):
    """Parse one constraint string into a matcher tuple.

    Returns a tuple ``(kind, lower, upper)`` where:
    - *kind* is one of ``'*'``, ``'=='``, ``'!='``, ``'>='``, ``'<='``, ``'>'``,
      ``'<'``, or ``'range'`` (for ``^`` and ``~``).
    - *lower* is a :class:`Version` or ``None``.
    - *upper* is an exclusive upper :class:`Version` or ``None`` (only for
      ``'range'`` kind).

    Raises ``ValueError`` on invalid input.
    """
    stripped = text.strip()
    if not stripped:
        raise ValueError("Empty constraint")

    for op in _OPERATORS:
        if stripped.startswith(op):
            rest = stripped[len(op):].strip()
            if not rest:
                raise ValueError(f"Missing version after operator {op!r}")
            ver = Version(rest)
            if op == '^':
                upper = _caret_upper_bound(ver)
                return ('range', ver, upper)
            if op == '~':
                upper = _tilde_upper_bound(ver)
                return ('range', ver, upper)
            return (op, ver, None)

    if stripped == '*':
        return ('*', None, None)

    # Bare version means exact match
    ver = Version(stripped)
    return ('==', ver, None)


class Range:
    """A set of version constraints; every constraint must be satisfied."""

    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError(
                f"Range spec must be a string, got {type(spec).__name__}"
            )
        if not spec.strip():
            raise ValueError("Empty range spec")

        # Normalized form for __str__: remove all whitespace characters
        self._normalized = ''.join(spec.split())

        # Parse each comma-separated constraint
        self._matchers = []
        for part in spec.split(','):
            self._matchers.append(_parse_single_constraint(part))

    def __str__(self):
        return self._normalized

    def contains(self, version):
        """Return ``True`` if *version* satisfies every constraint."""
        for kind, lower, upper in self._matchers:
            if kind == '*':
                continue
            elif kind == '==':
                if version != lower:
                    return False
            elif kind == '!=':
                if version == lower:
                    return False
            elif kind == '>=':
                if version < lower:
                    return False
            elif kind == '<=':
                if version > lower:
                    return False
            elif kind == '>':
                if version <= lower:
                    return False
            elif kind == '<':
                if version >= lower:
                    return False
            elif kind == 'range':
                # >= lower AND < upper  (used by ^ and ~)
                if version < lower:
                    return False
                if version >= upper:
                    return False
        return True

    def __contains__(self, version):
        return self.contains(version)
